import{_ as a,C as n,o as r,c as l,j as t,a as o,E as s,a2 as d}from"./chunks/framework.D0xy3_1I.js";const A=JSON.parse('{"title":"Art and audio","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/art-audio.md","filePath":"gdd/art-audio.md"}'),p={name:"gdd/art-audio.md"},c={id:"a-1-current-state",tabindex:"-1"},h={id:"a-3-animation-and-expressions-wanted-from-the-artist",tabindex:"-1"},u={id:"a-5-audio",tabindex:"-1"},g={id:"a-6-3d-fish-models-test",tabindex:"-1"};function m(f,e,b,y,k,w){const i=n("Badge");return r(),l("div",null,[e[12]||(e[12]=t("h1",{id:"art-and-audio",tabindex:"-1"},[o("Art and audio "),t("a",{class:"header-anchor",href:"#art-and-audio","aria-label":'Permalink to "Art and audio"'},"​")],-1)),t("h2",c,[e[0]||(e[0]=o("A.1 Current state ",-1)),s(i,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#a-1-current-state","aria-label":'Permalink to "A.1 Current state <Badge type="tip" text="Live" />"'},"​",-1))]),e[13]||(e[13]=d('<ul><li>Fish are 2D PNGs (side view) inflated into pillow meshes. No skeletal animation and no expressions yet; only a code-built blink lid on some species.</li><li>Everything that is not a fish is a code-built shape used as a placeholder: urchin, jellyfish, squid, clam, rocks, houses, columns, seaweed, pump tube, food bucket, pearl.</li><li>UI (HUD, target tanks, tools, popups, level list) is drawn by Phaser in code in a brass-and-glass aquarium style, with the Lilita One font. It reads from hidden HTML elements. No official UI art yet; the shapes are placeholders that real art can replace piece by piece.</li><li>No icon or store art.</li></ul><h2 id="a-2-fish-image-requirements-current-pipeline" tabindex="-1">A.2 Fish image requirements (current pipeline) <a class="header-anchor" href="#a-2-fish-image-requirements-current-pipeline" aria-label="Permalink to &quot;A.2 Fish image requirements (current pipeline)&quot;">​</a></h2><ul><li>Transparent PNG, <strong>side view, head to one side</strong>, clear silhouette. A fish covers only a few dozen pixels on screen, so <strong>big eyes, contrasting colours and a readable shape</strong> matter more than fine detail.</li><li>Code crops to the opaque area, finds the eye (dark round area) and generates thickness. If the eye is unclear, the blink lid will not show.</li><li>The dark outline is generated from the fish&#39;s own colour. <strong>Do not paint a black outline.</strong></li><li>Keep species clearly different in shape and colour: decoys include hue-rotated copies of targets, so already-similar originals make levels unfair.</li><li>The fish are 49 3D models in <code>public/models/fish/</code> (source: <code>Fish Asset 3D/3D model</code>, one <code>model.fbx</code> and one <code>tex.jpg</code> each). <strong>For a new fish:</strong> one mesh, one texture, the eyes drawn on the texture with a dark pupil and a white highlight, the nose to +x or +z (list the file in <code>FACES_Z</code> if it faces z). The old Unity set, <code>blue_white_babe</code> and the 2D pictures are no longer used.</li></ul>',3)),t("h2",h,[e[3]||(e[3]=o("A.3 Animation and expressions wanted from the artist ",-1)),s(i,{type:"warning",text:"Coming soon"}),e[4]||(e[4]=o()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#a-3-animation-and-expressions-wanted-from-the-artist","aria-label":'Permalink to "A.3 Animation and expressions wanted from the artist <Badge type="warning" text="Coming soon" />"'},"​",-1))]),e[14]||(e[14]=d('<p>None of this is integrated yet. Everything else (bounce on spawn, shake on touch, flying into the tray, bubbles, ink, light rays, water splashes, schooling) is done in code.</p><p><strong>Loop clips (30 fps, in place):</strong></p><table tabindex="0"><thead><tr><th>Clip</th><th>Description</th></tr></thead><tbody><tr><td>Swim</td><td>S-shaped body bend, fanned tail, pectoral fins flapping, seamless loop. Code scales playback speed, so one clip is enough</td></tr><tr><td>Hover</td><td>Almost still, only pectoral fins and tail move slightly</td></tr></tbody></table><p><strong>5 face expressions (blendshape or face texture swap):</strong></p><table tabindex="0"><thead><tr><th>Expression</th><th>Eyes</th><th>Mouth</th><th>Fins / body</th><th>Used when</th></tr></thead><tbody><tr><td>Neutral</td><td>Medium, round, pupil centred, blink (~0.2 s, every 2–5 s)</td><td>Closed, corners slightly up</td><td>Relaxed</td><td>Normal</td></tr><tr><td>Happy</td><td>Curved ^ ^ (or big round with highlight), slightly puffed cheeks</td><td>Wide smile, may be open</td><td>Pectoral fins slightly up</td><td>Correct fish, celebration</td></tr><tr><td>Scared</td><td>Very big round, tiny pupil</td><td>Crooked, small open, trembling</td><td>Fins stiff upright, body tucked</td><td>Near urchin / squid, tapped, pushed from tube</td></tr><tr><td>Sad</td><td>Big, outer corners drooping, pupil looking down</td><td>Closed, curved down</td><td>Fins drooping, tail low</td><td>Wrong tap, sent to Backup</td></tr><tr><td>Surprised</td><td>Big round, tiny pupil, lid fully open</td><td>Round O</td><td>Fins slightly spread</td><td>Just spawned, caught, startled by a falling object</td></tr></tbody></table><p>Optional if time allows: <strong>Dizzy</strong> (swirl eyes, covered in ink) and <strong>Eating</strong> (chewing mouth, feeding scene).</p><p>Convention: keep the same bone names and the same eye and mouth positions across species so code can share logic. Special species (seahorse, puffer, whale) may need their own Swim clip.</p><h2 id="a-4-other-art-to-consider" tabindex="-1">A.4 Other art to consider <a class="header-anchor" href="#a-4-other-art-to-consider" aria-label="Permalink to &quot;A.4 Other art to consider&quot;">​</a></h2><ul><li>Real models for urchin, jellyfish, squid, clam, pearl, food bucket. Code reads sizes from bounding boxes, so replacing a model means re-checking <a href="./rules#_3-8-collision">collision</a>.</li><li>Decoration sets for the 5 themes.</li><li>Official UI kit: buttons, Backup tray, target tanks, win/lose popups, stars.</li><li>App icon and store images.</li></ul>',9)),t("h2",u,[e[6]||(e[6]=o("A.5 Audio ",-1)),s(i,{type:"tip",text:"Live"}),e[7]||(e[7]=o()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#a-5-audio","aria-label":'Permalink to "A.5 Audio <Badge type="tip" text="Live" />"'},"​",-1))]),e[15]||(e[15]=d("<p>All audio is placeholder sound synthesized in code (WebAudio). No sound files and no background music (an <code>ambient()</code> function exists but is off). 13 sounds exist: <code>ui</code>, <code>miss</code>, <code>scatter</code>, <code>good</code>, <code>bad</code>, <code>junk</code>, <code>land</code>, <code>complete</code>, <code>win</code>, <code>lose</code>, <code>hint</code>, <code>splash</code>, <code>plip</code>, <code>start</code>.</p><p><strong>Missing sounds:</strong> tube shaking and cap opening, food bucket pouring, fish eating, fish head-butting, squid ink spray, clam opening and closing, swarm. A real SFX set and background music are also needed.</p><p>To swap sounds, edit <code>Snd</code> at the top of <code>game/src/main.js</code> (about lines 22–74). Keep the event names (<code>Snd.play(&#39;good&#39;)</code>) and change what is inside to play files.</p>",3)),t("h2",g,[e[9]||(e[9]=o("A.6 3D fish models (test) ",-1)),s(i,{type:"warning",text:"Test"}),e[10]||(e[10]=o()),e[11]||(e[11]=t("a",{class:"header-anchor",href:"#a-6-3d-fish-models-test","aria-label":'Permalink to "A.6 3D fish models (test) <Badge type="warning" text="Test" />"'},"​",-1))]),e[16]||(e[16]=d("<p>A rigged <code>.fbx</code> fish can be used instead of a 2D image. Put <code>model.fbx</code> and the atlas <code>Full.png</code> in <code>public/models/&lt;key&gt;/</code>, then add an entry to <code>MODEL_DEFS</code> in <code>game/src/main.js</code> (<code>key</code>, <code>fbx</code>, <code>png</code>, <code>len</code>). Requirements seen so far: units in cm, the fish faces +Z, the atlas is in the second UV set, one <code>Swim</code> clip. Level L16 (<code>&quot;onlyFish&quot;: &quot;&lt;key&gt;&quot;</code>) fills the tank with this model. Cost: about 8 skinned meshes and 121 bones per fish, so merge meshes or reduce bones before shipping to mobile.</p>",1))])}const _=a(p,[["render",m]]);export{A as __pageData,_ as default};
